select a.wi_name as WI_NAME,ROW_NUMBER() OVER (ORDER BY b.FACILITY, a.PRODUCT) AS sr_no, b.FACILITY as fac_name_n,a.product as PRODUCT_n,concat(concat(a.PRODUCT,'-'),b.FACILITY) as fac_code_n,  concat(concat(concat(concat('Request Type: ',a.REQUEST_TYPE),'</br>'),'Currency: ') ,a.CURRENCY) as req_ccy_n,a.DETAILED_FAC_PURPOSE as purpose_n, a.TENOR_IN_MONTHS as tenure_n, a.P_EFFEC_INT_RATE as int_rate_n, TO_CHAR(a.EQUI_AMT_IN_HOME_CURR, '999,999,999.99') as last_approved_n,TO_CHAR(a.CURRENT_OUTSTANDING, '999,999,999.99') as current_exposure_n, a.CURRENCY as amount_n, case  when a.REQUEST_TYPE!= 'New' then 'NA'  end as  limit_now_n, '' as expiry_n , '' as review_n from  ng_clos_borrower_newloans a, NGM_CLOS_FACILITY b  where a.PRODUCT=b.FACILITY_CODE and a.wi_name = '#wi_name#' 